"""Remux an MCAP recording into a byte-unique copy for upload, shifting all times by ``time_offset_ns``."""

from __future__ import annotations

import json

from mcap.reader import make_reader
from mcap.writer import Writer

# Metadata record name carrying the per-run nonce that makes the copy unique.
_RUN_METADATA_NAME = "foxglove-wizard-run"

# Writer library string identifying copies produced by this tool.
_LIBRARY = "foxglove-wizard"

# A synthetic marker topic baked into the uploaded copy so the Foxglove app can identify this
# recording as the onboarding quickstart sample and exclude it from activation metrics. Kept in
# sync with the live stream's marker in player.py.
_DEVICE_NAME_TOPIC = "/foxglove_sample_stream/device_name"
_DEVICE_NAME_SCHEMA_NAME = "foxglove_wizard_sample/DeviceName"
_DEVICE_NAME_VALUE = "onboarding-quickstart-wizard"


def remux_mcap(source_path: str, dest_path: str, *, nonce: str, time_offset_ns: int = 0) -> None:
    """Write a byte-unique copy of ``source_path`` to ``dest_path``."""
    with open(source_path, "rb") as source_handle:
        reader = make_reader(source_handle)
        header = reader.get_header()

        with open(dest_path, "wb") as dest_handle:
            writer = Writer(dest_handle)
            writer.start(profile=header.profile, library=_LIBRARY)

            schema_id_map: dict[int, int] = {0: 0}
            channel_id_map: dict[int, int] = {}

            summary = reader.get_summary()
            if summary is None:
                raise RuntimeError("MCAP file has no summary section; cannot remux it.")

            for schema_id, schema in summary.schemas.items():
                schema_id_map[schema_id] = writer.register_schema(
                    name=schema.name, encoding=schema.encoding, data=schema.data
                )
            for channel_id, channel in summary.channels.items():
                channel_id_map[channel_id] = writer.register_channel(
                    topic=channel.topic,
                    message_encoding=channel.message_encoding,
                    schema_id=schema_id_map.get(channel.schema_id, 0),
                    metadata=channel.metadata,
                )

            device_schema_id = writer.register_schema(
                name=_DEVICE_NAME_SCHEMA_NAME,
                encoding="jsonschema",
                data=json.dumps(
                    {"type": "object", "properties": {"name": {"type": "string"}}}
                ).encode("utf-8"),
            )
            device_channel_id = writer.register_channel(
                topic=_DEVICE_NAME_TOPIC,
                message_encoding="json",
                schema_id=device_schema_id,
            )
            # One message is enough for the app to see the topic. Write it at the recording start so
            # it stays in log-time order with the copied messages.
            stats = summary.statistics
            start_ns = stats.message_start_time if stats else 0
            writer.add_message(
                channel_id=device_channel_id,
                log_time=start_ns + time_offset_ns,
                data=json.dumps({"name": _DEVICE_NAME_VALUE}).encode("utf-8"),
                publish_time=start_ns + time_offset_ns,
                sequence=0,
            )

            for _schema, channel, message in reader.iter_messages():
                writer.add_message(
                    channel_id=channel_id_map[channel.id],
                    log_time=message.log_time + time_offset_ns,
                    data=message.data,
                    publish_time=message.publish_time + time_offset_ns,
                    sequence=message.sequence,
                )

            for attachment in reader.iter_attachments():
                writer.add_attachment(
                    create_time=attachment.create_time + time_offset_ns,
                    log_time=attachment.log_time + time_offset_ns,
                    name=attachment.name,
                    media_type=attachment.media_type,
                    data=attachment.data,
                )
            for metadata in reader.iter_metadata():
                writer.add_metadata(metadata.name, metadata.metadata)

            writer.add_metadata(_RUN_METADATA_NAME, {"run": nonce})
            writer.finish()
